namespace {

// COMMAND index of the first abstract write targeting regno, if any.
auto first_cmd_idx(const std::vector<DmiOp>& ops, uint16_t regno)
  -> std::optional<std::size_t>
{
  for (std::size_t i = 0; i < ops.size(); ++i) {
    const auto& op = ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xffffu) == regno)
      return i;
  }
  return std::nullopt;
}

}  // namespace

TEST_CASE("with HYBRID_FLAG_FP the driver programs f0 (minimal: not f1..f31)")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x2000ULL;  // FS = Initial already
  s.fpr[0] = 0x1122334455667788ULL;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  CHECK(contains_regno(ns, hybrid::regno_fpr(0)));
  // Minimal slice: only f0 is programmed; f1..f31 arrive in the completion.
  CHECK_FALSE(contains_regno(ns, hybrid::regno_fpr(1)));
  CHECK_FALSE(contains_regno(ns, hybrid::regno_fpr(31)));
}

TEST_CASE("mstatus (FS enable) is written before the FPR abstract command")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x2000ULL;
  s.fpr[0] = 0xabcd;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto mstatus_idx = first_cmd_idx(bus.ops, hybrid::regno_csr(0x300));
  const auto fpr_idx     = first_cmd_idx(bus.ops, hybrid::regno_fpr(0));
  REQUIRE(mstatus_idx);
  REQUIRE(fpr_idx);
  CHECK(*mstatus_idx < *fpr_idx);
}

TEST_CASE("FPR write carries its state value via DATA0/DATA1 before the COMMAND")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  constexpr uint64_t f0 = 0xCAFEF00D'12345678ULL;
  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x2000ULL;
  s.fpr[0] = f0;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto fpr_cmd = first_cmd_idx(bus.ops, hybrid::regno_fpr(0));
  REQUIRE(fpr_cmd);
  REQUIRE(*fpr_cmd >= 2);
  const auto& d0 = bus.ops[*fpr_cmd - 2];
  const auto& d1 = bus.ops[*fpr_cmd - 1];
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(f0 & 0xffffffffu));
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t((f0 >> 32) & 0xffffffffu));
}

TEST_CASE("B4: drained mstatus.FS = Off still writes mstatus with FS forced Initial")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_FP;
  s.mstatus = 0x0ULL;  // FS = Off in the drained state
  s.fpr[0] = 0x1;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // mstatus (0x300) is still programmed, and DATA0 carries FS = Initial even
  // though the drained field was Off -- otherwise the FPR write would NACK.
  const auto mstatus_cmd = first_cmd_idx(bus.ops, hybrid::regno_csr(0x300));
  REQUIRE(mstatus_cmd);
  REQUIRE(*mstatus_cmd >= 2);
  const auto& d0 = bus.ops[*mstatus_cmd - 2];
  CHECK(d0.reg == kData0);
  CHECK((d0.value & 0x6000u) == 0x2000u);  // FS = Initial forced
}

